// The mount scenario's own run (#340, not ported from drawerdeck's bench:
// drawerdeck has no mount scenario). One static page per (deck, n, dirty,
// mode) cell, generated by `scripts/generate-mount-pages.mjs` into `dist/`
// from each deck's SSR bundle (`vite.ssr.config.ts`) -- see that script's
// own header comment for the filename convention this file's `mountUrl`
// repeats.
//
// Scored the same way the gesture bench is (one JSON line per run, to
// `results/mount.jsonl`; interleaved, with a discarded warm-up rep; a
// seeded, reproducible shuffle), but the trace window itself is new: from
// `bench-mount-start` (the client entry's own first line, before
// `createRoot`/`hydrateRoot` runs) to the first presented frame at or after
// every rendered instance has published its own state
// (`window.__mount.published()`, polled with `page.waitForFunction` --
// never a fixed wall-clock window, which a CPU-throttled page can starve to
// only a frame or two of real progress, #340's own mount lessons).
//
// A fresh Playwright page starts on `about:blank`, whose first navigation
// away sometimes lands in a different renderer process than the one that
// then serves same-origin navigations after it (Chromium's process-per-site
// model). The CDP `Tracing` session this file attaches is bound to one
// target, so starting it before that first, possibly process-swapping
// navigation would risk silently losing every later trace event. Each test
// here navigates once to an already-built gesture bench page on this
// origin first, discarded, then attaches the CDP session and navigates a
// second time, same-origin, to the real mount page: a same-site navigation
// does not swap renderer process under Chromium's default isolation, so
// the trace started before it survives.

import { appendFileSync, mkdirSync, writeFileSync } from 'node:fs';
import { fileURLToPath, URL } from 'node:url';
import { gzipSync } from 'node:zlib';
import type { Page } from '@playwright/test';
import { test } from '@playwright/test';
import { DECKS } from './decks';
import { makeRng, resolveSeed, shuffle } from './seed';
import {
  analyzeMount,
  captureTrace,
  frameTimeline,
  type TraceEvent
} from './trace';
import type {} from './src/mount/harness';

const OUT = fileURLToPath(new URL('./results/', import.meta.url));
const TRACE_DIR = fileURLToPath(
  new URL('./results/mount-traces/', import.meta.url)
);
mkdirSync(OUT, { recursive: true });
mkdirSync(TRACE_DIR, { recursive: true });

const SHARD_ID = process.env.SHARD_ID ?? 'local';
const SEED = resolveSeed();
writeFileSync(`${OUT}mount-seed.txt`, `${SEED}\n`);
const rng = makeRng(SEED);

function record(row: Record<string, unknown>): void {
  appendFileSync(`${OUT}mount.jsonl`, `${JSON.stringify(row)}\n`);
}

const MOUNT_N = [2, 20] as const;
const MOUNT_DIRTY = [false, true] as const;
const MOUNT_MODES = ['ssr', 'csr'] as const;
const MOUNT_REPS = Number(process.env.MOUNT_REPS ?? 3);

/** Mirrors `scripts/generate-mount-pages.mjs`'s own filename convention --
 * see that script's header comment. */
function mountUrl(
  deckKey: string,
  n: number,
  dirty: boolean,
  mode: 'ssr' | 'csr'
): string {
  return `mount-${deckKey}-n${n}-${dirty ? 'dirty' : 'clean'}-${mode}.html`;
}

const CLOSE_WAIT_MS = 20_000;

async function runMountPass(
  page: Page,
  url: string
): Promise<{
  events: TraceEvent[];
}> {
  // Warms this origin's renderer process (see this file's own header
  // comment) with a cheap, already-built page, discarded.
  await page.goto('bench-carouseldeck.html');

  const cdp = await page.context().newCDPSession(page);
  // 4x CPU throttle, the same rate #333's own mount-bench evidence used:
  // a quiet CI runner under-states a forced layout's real cost on a
  // mid-range device. Safe to combine with a condition-based wait
  // (`page.waitForFunction` below), unlike a fixed-window rAF probe, which
  // #340's own mount lessons warn can see only 1-3 frames under throttle.
  await cdp.send('Emulation.setCPUThrottlingRate', { rate: 4 });
  const events = await captureTrace(cdp, async () => {
    await page.goto(url);
    await page.waitForFunction(
      () => window.__mount !== undefined && window.__mount.published(),
      null,
      { timeout: CLOSE_WAIT_MS }
    );
    await page.evaluate(() => window.__mount.markPublished());
    // One extra rAF pair so the "first frame after published" this marks
    // has actually had a chance to present before tracing stops.
    await page.evaluate(
      () =>
        new Promise<void>((resolve) =>
          requestAnimationFrame(() => requestAnimationFrame(() => resolve()))
        )
    );
  });
  await cdp.detach();
  return { events };
}

for (const n of MOUNT_N) {
  for (const dirty of MOUNT_DIRTY) {
    for (const mode of MOUNT_MODES) {
      for (let rep = 0; rep < MOUNT_REPS; rep++) {
        // A fresh shuffle per (n, dirty, mode, rep): the five decks never
        // run back to back as a block (the same interleaving rule the
        // gesture bench follows, #266 rule 1).
        const order = shuffle(DECKS, rng);
        for (const deck of order) {
          test(`[${deck.key}] mount n=${n} ${dirty ? 'dirty' : 'clean'} ${mode} rep=${rep}`, async ({
            page
          }) => {
            const url = mountUrl(deck.key, n, dirty, mode);

            // Warm-up, discarded (the gesture bench's own rule 6): a fresh
            // page per rep already isolates this run from JIT/caching
            // effects a later rep on the same page could ride on, so this
            // is one extra pass on a freshly reloaded page, not a reused
            // first rep.
            const warmup = await runMountPass(page, url);
            const warmupMount = analyzeMount(warmup.events);
            record({
              shard: SHARD_ID,
              seed: SEED,
              deck: deck.key,
              n,
              dirty,
              mode,
              rep,
              warmup: true,
              mount: warmupMount
            });

            const scored = await runMountPass(page, url);
            const mount = analyzeMount(scored.events);

            const fileBase = `${deck.key}__n${n}__${dirty ? 'dirty' : 'clean'}__${mode}__rep${rep}__${SHARD_ID}`;
            writeFileSync(
              `${TRACE_DIR}${fileBase}.trace.json.gz`,
              gzipSync(Buffer.from(JSON.stringify(scored.events)))
            );
            writeFileSync(
              `${TRACE_DIR}${fileBase}.frames.json`,
              JSON.stringify(frameTimeline(scored.events))
            );

            record({
              shard: SHARD_ID,
              seed: SEED,
              deck: deck.key,
              n,
              dirty,
              mode,
              rep,
              warmup: false,
              mount
            });
          });
        }
      }
    }
  }
}
